uk.v13.ms.console.example:
# Консоль ModScript: пишіть команди й дивіться праворуч вивід,
# змінні та те, що буде в моді.
let price = 40
repeat 3 {
  inc price 5
}
print "Ціна: $price"

option Difficulty = normal easy normal hard
recipe "Berry Pie" = "296 1 246 1/1 10/0/default"
edit "Data/Objects" "472" Price = $price

switch $Difficulty {
  case easy {
    print "легко"
  }
  default {
    print "як задумано"
  }
}
debug price

